// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/**
 * BiggiLiquidityHelperReader
 * View helper pro FE: router info, swap path a rychlý preview párování.
 * Čte ze stávajících LM/Reserve/Vault kontraktů, nepíše žádný stav.
 */

interface ILiquidityManagerView {
    function BIGGI() external view returns (address);
    function router() external view returns (address);
    function factory() external view returns (address);
}

interface IReserveView {
    function dexRefillBiggi() external view returns (uint256);
    function polBalance() external view returns (uint256);
}

interface IVaultView {
    function whitelistedPairs(address lpPair) external view returns (bool);
    function lpBalanceOf(address lpPair) external view returns (uint256);
}

interface IUniswapV2RouterView {
    function WETH() external view returns (address);
    function getAmountsOut(uint amountIn, address[] calldata path) external view returns (uint[] memory amounts);
}

contract BiggiLiquidityHelperReader {
    ILiquidityManagerView public immutable lm;
    IReserveView public immutable reserve;
    IVaultView public immutable vault;
    IUniswapV2RouterView public immutable router;

    constructor(address reserve_, address lm_, address vault_, address router_) {
        require(reserve_ != address(0) && lm_ != address(0) && vault_ != address(0) && router_ != address(0), "zero addr");
        reserve = IReserveView(reserve_);
        lm = ILiquidityManagerView(lm_);
        vault = IVaultView(vault_);
        router = IUniswapV2RouterView(router_);
    }

    function routerInfo() external view returns (address routerAddr, address factory, address weth) {
        routerAddr = address(router);
        factory = lm.factory();
        weth = router.WETH();
    }

    function getSwapPath() external view returns (address[] memory p) {
        p = new address[](2);
        p[0] = router.WETH();
        p[1] = lm.BIGGI();
    }

    /// @notice Náhled kolik BIGGI bude potřeba pro požadované POL (bez slippage úprav)
    function liquidityPreview(uint256 requestedPolWei) external view returns (
        uint256 tokenDesired,
        uint256[] memory amountsOutPath,
        uint256 reservePol,
        uint256 dexRefillBiggi
    ) {
        reservePol = reserve.polBalance();
        dexRefillBiggi = reserve.dexRefillBiggi();

        address[] memory path = new address[](2);
        path[0] = router.WETH();
        path[1] = lm.BIGGI();

        try router.getAmountsOut(requestedPolWei, path) returns (uint256[] memory amounts) {
            amountsOutPath = amounts;
            if (amounts.length >= 2) {
                tokenDesired = amounts[1];
            }
        } catch {
            // necháme defaultní nuly
        }
    }

    function vaultInfo(address lpPair) external view returns (bool pairWhitelisted, uint256 vaultLpBalance) {
        pairWhitelisted = vault.whitelistedPairs(lpPair);
        vaultLpBalance = vault.lpBalanceOf(lpPair);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/**
 * BiggiMainReader - lehký view agregátor pro BiggiEyesMain.
 * Přidává helpery požadované FE: getMintDataByTokenId, findTicket a hromadné snapshoty.
 * Nepíšeme žádný stav; jen čteme z hlavního kontraktu.
 */

import "./Library/BiggiIdIndexLib.sol";

interface IBiggiMainMinimal {
    function exists(uint256 tokenId) external view returns (bool);
    function ownerOf(uint256 tokenId) external view returns (address);
    function tokenURI(uint256 tokenId) external view returns (string memory);

    function getCurrentBlockPrice(uint16 blockIdx) external view returns (uint256);
    function getMintData(uint256 index) external view returns (uint256, uint256, uint256);

    function ticketPrice() external view returns (uint256);
    function ticketMinted() external view returns (uint16);
    function biggiMinted() external view returns (uint16);

    function blockMintCounts(uint256 i) external view returns (uint16);
    function backgroundMintCounts(uint256 i) external view returns (uint16);

    function orangeWinnersCount() external view returns (uint8);
    function blockWinnersCount() external view returns (uint8);
    function rainbowRewardClaimedGlobal() external view returns (bool);
    function characterClaimed(uint16 blk) external view returns (bool);
}

contract BiggiMainReader {
    using BiggiIdIndexLib for uint256;

    IBiggiMainMinimal public immutable main;

    constructor(address mainContract) {
        require(mainContract != address(0), "main=0");
        main = IBiggiMainMinimal(mainContract);
    }

    /* ============== Hromadné pohledy ============== */

    function getAllBlockPrices() external view returns (uint256[10] memory prices) {
        for (uint256 i = 0; i < 10; i++) {
            prices[i] = main.getCurrentBlockPrice(uint16(i + 1));
        }
    }

    function getAllBlockMintCounts() external view returns (uint16[10] memory counts) {
        for (uint256 i = 0; i < 10; i++) {
            counts[i] = main.blockMintCounts(i);
        }
    }

    function getAllBackgroundMintCounts() external view returns (uint16[10] memory counts) {
        for (uint256 i = 0; i < 10; i++) {
            counts[i] = main.backgroundMintCounts(i);
        }
    }

    // Mint-time data podle tokenId (pro NftCard)
    function getMintDataByTokenId(uint256 tokenId) external view returns (
        uint256 ticketPrice_,
        uint256 blockPrice_,
        uint256 finalPrice_
    ) {
        if (!main.exists(tokenId)) return (0, 0, 0);
        if (tokenId < BiggiIdIndexLib.BIGGI_OFFSET || tokenId >= BiggiIdIndexLib.CHARACTER_OFFSET) {
            return (0, 0, 0);
        }
        uint256 idx = BiggiIdIndexLib.nftIndexFromTokenId(tokenId);
        return main.getMintData(idx);
    }

    // Souhrn odměn + kolik charakterů už padlo
    function getRewardsCounters() external view returns (
        uint8 orange,
        uint8 blockWinners,
        bool rainbow,
        uint8 charactersMinted
    ) {
        orange = main.orangeWinnersCount();
        blockWinners = main.blockWinnersCount();
        rainbow = main.rainbowRewardClaimedGlobal();

        uint8 c;
        for (uint16 i = 1; i <= 10; i++) {
            if (main.characterClaimed(i)) {
                unchecked { c++; }
            }
        }
        charactersMinted = c;
    }

    // Snapshot pro dashboard jedním voláním
    function getFrontendSnapshot()
        external
        view
        returns (
            // základ
            uint256 ticketPriceWei,
            uint16 ticketMinted_,
            uint16 biggiMinted_,
            // pole
            uint256[10] memory currentBlockPrices,
            uint16[10] memory blocksMinted,
            uint16[10] memory bgsMinted,
            // odměny
            uint8 orange_,
            uint8 blockWinners_,
            bool rainbow_,
            uint8 charactersMinted_
        )
    {
        ticketPriceWei   = main.ticketPrice();
        ticketMinted_    = main.ticketMinted();
        biggiMinted_     = main.biggiMinted();

        for (uint256 i = 0; i < 10; i++) {
            currentBlockPrices[i] = main.getCurrentBlockPrice(uint16(i + 1));
            blocksMinted[i]       = main.blockMintCounts(i);
            bgsMinted[i]          = main.backgroundMintCounts(i);
        }

        orange_        = main.orangeWinnersCount();
        blockWinners_  = main.blockWinnersCount();
        rainbow_       = main.rainbowRewardClaimedGlobal();

        uint8 c;
        for (uint16 j = 1; j <= 10; j++) {
            if (main.characterClaimed(j)) { unchecked { c++; } }
        }
        charactersMinted_ = c;
    }

    /// @notice Najde všechny ticket tokenId, které vlastní daná adresa (range 1..MAX_TICKETS)
    function findTicket(address owner) external view returns (uint256[] memory out) {
        uint256 minted = main.ticketMinted();
        if (minted == 0) return out;

        uint256[] memory buf = new uint256[](minted);
        uint256 found;
        for (uint256 i = 0; i < minted; i++) {
            uint256 tokenId = BiggiIdIndexLib.TICKET_OFFSET + i;
            // existuje a vlastní ho daná adresa?
            if (main.exists(tokenId) && main.ownerOf(tokenId) == owner) {
                buf[found] = tokenId;
                unchecked { found++; }
            }
        }
        out = new uint256[](found);
        for (uint256 j = 0; j < found; j++) {
            out[j] = buf[j];
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/**
 * Rozšířený reader pro MultiCollectionDistributor.
 * Přidává snapshot a aliasy pendingů, které UI postrádalo.
 */

interface IMultiCollectionDistributorMinimal {
    function collectionRewards() external view returns (address);
    function reserve() external view returns (address);
    function buybackAgent() external view returns (address);
    function treasury() external view returns (address);
    function communityCenter() external view returns (address);

    function totalPending() external view returns (uint256);
    function pending(address who) external view returns (uint256);
    function totalReceived() external view returns (uint256);
    function receivedByCollection(address coll) external view returns (uint256);
    function collections(address coll) external view returns (bool);
}

contract BiggiMultiCollectionDistributorReaderV2 {
    IMultiCollectionDistributorMinimal public immutable distributor;

    struct Snapshot {
        address collectionRewards;
        address reserve;
        address buybackAgent;
        address treasury;
        address communityCenter;
        uint256 totalPending;
        uint256 totalReceived;
    }

    constructor(address distributor_) {
        require(distributor_ != address(0), "zero distributor");
        distributor = IMultiCollectionDistributorMinimal(distributor_);
    }

    function globalSnapshot() external view returns (Snapshot memory s) {
        s.collectionRewards = distributor.collectionRewards();
        s.reserve = distributor.reserve();
        s.buybackAgent = distributor.buybackAgent();
        s.treasury = distributor.treasury();
        s.communityCenter = distributor.communityCenter();
        s.totalPending = distributor.totalPending();
        s.totalReceived = distributor.totalReceived();
    }

    function pendingCommunity() external view returns (uint256) {
        return distributor.pending(distributor.communityCenter());
    }

    function pendingOf(address[] calldata who) external view returns (uint256[] memory out) {
        uint256 n = who.length;
        out = new uint256[](n);
        for (uint256 i = 0; i < n; i++) {
            out[i] = distributor.pending(who[i]);
        }
    }

    function receivedOfCollections(address[] calldata colls) external view returns (uint256[] memory out) {
        uint256 n = colls.length;
        out = new uint256[](n);
        for (uint256 i = 0; i < n; i++) {
            out[i] = distributor.receivedByCollection(colls[i]);
        }
    }

    function whitelisted(address[] calldata colls) external view returns (bool[] memory out) {
        uint256 n = colls.length;
        out = new bool[](n);
        for (uint256 i = 0; i < n; i++) {
            out[i] = distributor.collections(colls[i]);
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/**
 * BiggiReserveTreasuryReader
 * Kompaktní snapshoty pro Reserve a Treasury, aby FE nemusel volat více getterů.
 */

interface IReserveSnapshotView {
    function polBalance() external view returns (uint256);
    function biggiBalance() external view returns (uint256);
    function waitingBiggi() external view returns (uint256);
    function dexRefillBiggi() external view returns (uint256);
    function totalPolReceived() external view returns (uint256);
}

interface ITreasurySnapshotView {
    function polBalance() external view returns (uint256);
    function biggiBalance() external view returns (uint256);
    function totalBiggiReceivedFromBuyback() external view returns (uint256);
    function totalPolReceivedFromDistributor() external view returns (uint256);
}

contract BiggiReserveTreasuryReader {
    IReserveSnapshotView public immutable reserve;
    ITreasurySnapshotView public immutable treasury;

    constructor(address reserve_, address treasury_) {
        require(reserve_ != address(0) && treasury_ != address(0), "zero addr");
        reserve = IReserveSnapshotView(reserve_);
        treasury = ITreasurySnapshotView(treasury_);
    }

    function reserveSnapshot() external view returns (
        uint256 reservePol,
        uint256 reserveBiggi,
        uint256 waiting,
        uint256 dexRefill,
        uint256 totalReceivedPol
    ) {
        reservePol = reserve.polBalance();
        reserveBiggi = reserve.biggiBalance();
        waiting = reserve.waitingBiggi();
        dexRefill = reserve.dexRefillBiggi();
        totalReceivedPol = reserve.totalPolReceived();
    }

    function treasurySnapshot() external view returns (
        uint256 treasuryPol,
        uint256 treasuryBiggi,
        uint256 totalBiggiFromBuyback,
        uint256 totalPolFromDistributor
    ) {
        treasuryPol = treasury.polBalance();
        treasuryBiggi = treasury.biggiBalance();
        totalBiggiFromBuyback = treasury.totalBiggiReceivedFromBuyback();
        totalPolFromDistributor = treasury.totalPolReceivedFromDistributor();
    }
}

